BEGIN;
SELECT no_plan();
CREATE TEMP TABLE expense_create_fixture(input jsonb,request_id uuid,result jsonb);
INSERT INTO expense_create_fixture VALUES
 ('{"expense_type":"fuel","amount":1.005,"expense_date":"2026-10-19","vat_rate":15.555,"category":"  Fuel  ","vendor":"  Synthetic vendor  ","description":null}',gen_random_uuid(),NULL);
GRANT ALL ON expense_create_fixture TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
UPDATE expense_create_fixture SET result=public.create_expense_atomic(input,request_id);
SELECT is((SELECT result->>'replayed' FROM expense_create_fixture),'false','first request creates an expense');
SELECT is((SELECT tenant_id FROM public.expenses WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),
 '00000000-0000-0000-0000-000000000001'::uuid,'tenant derives from JWT');
SELECT is((SELECT created_by FROM public.expenses WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),
 '00000000-0000-0000-0000-000000000001'::uuid,'actor derives from JWT');
SELECT is((SELECT amount FROM public.expenses WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),1.01::numeric,'amount rounds in base ten');
SELECT is((SELECT vat_rate FROM public.expenses WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),15.56::numeric,'rate fits database precision');
SELECT is((SELECT vat_amount FROM public.expenses WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),0::numeric,'pending expense does not claim input VAT');
SELECT is((SELECT is_approved FROM public.expenses WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),false,'creation cannot approve expense');
SELECT is((SELECT category FROM public.expenses WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),'Fuel','optional text normalizes');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE entity_id=(SELECT (result->>'id')::uuid FROM expense_create_fixture) AND action='expense_created'),1,'creation audit is present once');
SELECT is((SELECT public.create_expense_atomic(input,request_id)->>'id' FROM expense_create_fixture),(SELECT result->>'id' FROM expense_create_fixture),'retry returns original ID');
SELECT is((SELECT public.create_expense_atomic(input,request_id)->>'replayed' FROM expense_create_fixture),'true','retry is identified');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE entity_id=(SELECT (result->>'id')::uuid FROM expense_create_fixture) AND action='expense_created'),1,'retry does not duplicate audit');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"amount":2}',request_id) FROM expense_create_fixture$$,'P0001','EXP_RETRY: request identifier already used for different details','changed payload cannot reuse identity');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"tenant_id":"00000000-0000-0000-0000-000000000002"}',gen_random_uuid()) FROM expense_create_fixture$$,'22023',NULL,'tenant injection denied');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"is_approved":true}',gen_random_uuid()) FROM expense_create_fixture$$,'22023',NULL,'approval injection denied');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"amount":"1.00"}',gen_random_uuid()) FROM expense_create_fixture$$,'22023',NULL,'numeric strings rejected');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"amount":0.001}',gen_random_uuid()) FROM expense_create_fixture$$,'22023',NULL,'rounded zero rejected');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"vat_rate":101}',gen_random_uuid()) FROM expense_create_fixture$$,'22023',NULL,'invalid VAT rejected');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"expense_date":"2026-02-30"}',gen_random_uuid()) FROM expense_create_fixture$$,'22008',NULL,'impossible date rejected');
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"amount":100000000}',gen_random_uuid()) FROM expense_create_fixture$$,'22003',NULL,'expense monetary overflow rejected');
SELECT throws_ok($$INSERT INTO public.expenses(tenant_id,expense_type,amount,expense_date) VALUES('00000000-0000-0000-0000-000000000001','fuel',1,'2026-10-19')$$,'42501',NULL,'direct caller insert cannot bypass creation audit');
SELECT throws_ok($$UPDATE public.expenses SET vendor='bypass' WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)$$,'42501',NULL,'direct caller update cannot modify managed expense');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.create_expense_atomic(input,gen_random_uuid()) FROM expense_create_fixture$$,'42501',NULL,'MFA enforced at RPC boundary');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
RESET ROLE;
SELECT throws_ok($$UPDATE public.expenses SET request_id=gen_random_uuid() WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)$$,'P0001','EXP_IDENTITY: expense request identity is immutable','service updates cannot change identity');
CREATE FUNCTION pg_temp.fail_expense_create_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.action='expense_created' THEN RAISE EXCEPTION 'synthetic expense audit fault';END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_expense_create_test_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_expense_create_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.create_expense_atomic(input||'{"vendor":"Atomic expense rollback fixture"}',gen_random_uuid()) FROM expense_create_fixture$$,'P0001','synthetic expense audit fault','audit failure aborts record creation');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.expenses WHERE vendor='Atomic expense rollback fixture'),0,'failed audit leaves no expense');
DROP TRIGGER trg_expense_create_test_audit ON public.audit_log;
SELECT lives_ok($$SELECT public.approve_expense_atomic('00000000-0000-0000-0000-000000000001',(SELECT (result->>'id')::uuid FROM expense_create_fixture),20,'recoverable','00000000-0000-0000-0000-000000000001')$$,'existing approval transaction accepts managed expense');
SELECT is((SELECT count(*)::int FROM public.payables WHERE source_entity_type='expense' AND source_entity_id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)),1,'approval produces one payable');
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.create_expense_atomic(input,request_id) FROM expense_create_fixture$$,'approval VAT changes do not invalidate creation retry');
RESET ROLE;
SELECT throws_ok($$UPDATE public.expenses SET deleted_at=now() WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture)$$,'P0001','EXP_HISTORY_IMMUTABLE','approved source cannot be hidden or removed by service cleanup');
SET LOCAL ROLE authenticated;
UPDATE expense_create_fixture SET request_id=gen_random_uuid(),result=NULL;
UPDATE expense_create_fixture SET result=public.create_expense_atomic(input,request_id);
RESET ROLE;
UPDATE public.expenses SET deleted_at=now() WHERE id=(SELECT (result->>'id')::uuid FROM expense_create_fixture);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.create_expense_atomic(input,request_id) FROM expense_create_fixture$$,'P0001','EXP_RETRY_UNAVAILABLE: original expense needs review','deleted expense cannot be reported as saved');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.create_expense_atomic('{}',gen_random_uuid())$$,'42501',NULL,'anonymous RPC denied');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT public.create_expense_atomic('{}',gen_random_uuid())$$,'42501',NULL,'service caller cannot impersonate JWT actor');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
